using Npgsql;
using AvenChart.Api.Models;
namespace AvenChart.Api.Data;
public sealed class TrackAnythingRepository(NpgsqlDataSource dataSource)
{
 public async Task<TrackAnythingResponse> GetAsync(CancellationToken ct){await using var c=await dataSource.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText="select id,parent_id,name,description,position,active from track_anything_types order by coalesce(parent_id,0),position,active desc,name;";var items=new List<TrackAnythingItem>();await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))items.Add(new(r.GetInt32(0),r.IsDBNull(1)?null:r.GetInt32(1),r.GetString(2),r.IsDBNull(3)?null:r.GetString(3),r.GetInt32(4),r.GetBoolean(5)));return new(items);}
 public async Task<TrackAnythingItem?> SaveAsync(int? id,TrackAnythingRequest x,CancellationToken ct){var name=Required(x.Name);await using var c=await dataSource.OpenConnectionAsync(ct);if(x.ParentId is not null&&!await Exists(c,x.ParentId.Value,ct))throw new ArgumentException("Parent track does not exist.");await using var q=c.CreateCommand();q.CommandText=id is null?"insert into track_anything_types(parent_id,name,description,position,active) values(@parent,@name,@description,@position,@active) returning id,parent_id,name,description,position,active;":"update track_anything_types set parent_id=@parent,name=@name,description=@description,position=@position,active=@active where id=@id returning id,parent_id,name,description,position,active;";if(id is not null)q.Parameters.AddWithValue("id",id.Value);q.Parameters.AddWithValue("parent",(object?)x.ParentId??DBNull.Value);q.Parameters.AddWithValue("name",name);q.Parameters.AddWithValue("description",string.IsNullOrWhiteSpace(x.Description)?DBNull.Value:x.Description.Trim());q.Parameters.AddWithValue("position",x.Position);q.Parameters.AddWithValue("active",x.Active??true);await using var r=await q.ExecuteReaderAsync(ct);return await r.ReadAsync(ct)?new(r.GetInt32(0),r.IsDBNull(1)?null:r.GetInt32(1),r.GetString(2),r.IsDBNull(3)?null:r.GetString(3),r.GetInt32(4),r.GetBoolean(5)):null;}
 public async Task<bool> DeleteAsync(int id,CancellationToken ct){await using var c=await dataSource.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText="delete from track_anything_types where id=@id;";q.Parameters.AddWithValue("id",id);return await q.ExecuteNonQueryAsync(ct)==1;}
 static async Task<bool> Exists(NpgsqlConnection c,int id,CancellationToken ct){await using var q=c.CreateCommand();q.CommandText="select exists(select 1 from track_anything_types where id=@id);";q.Parameters.AddWithValue("id",id);return (bool)(await q.ExecuteScalarAsync(ct)??false);} static string Required(string? s)=>string.IsNullOrWhiteSpace(s)||s.Trim().Length>120?throw new ArgumentException("Name is required and must be 120 characters or fewer."):s.Trim();
}
